#include <stdio.h>

/* 从 n 支试管中取 k 支的方案数（递归组合数） */
long long comb(int n, int k)
{
    if (k < 0 || k > n) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    return comb(n - 1, k - 1) + comb(n - 1, k);
}

int main(void)
{
    int n, k;

    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }
    printf("%lld\n", comb(n, k));
    return 0;
}

#include <stdio.h>

#define MAXLEN 1005

int main(void)
{
    char s[MAXLEN];
    int i = 0;
    int first = 1;

    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }
    while (s[i] != '\0') {
        if (s[i] == ' ' || s[i] == '\n' || s[i] == '\r') {
            i++;
            continue;
        }
        if (!first) {
            putchar(' ');       /* 单词之间只补一个空格 */
        }
        while (s[i] != '\0' && s[i] != ' ' && s[i] != '\n' && s[i] != '\r') {
            putchar(s[i]);
            i++;
        }
        first = 0;
    }
    putchar('\n');
    return 0;
}

