#define MAXLEN 512

/* 用两个指针就地反转 buf[left..right] 之间的字符 */
void reverse_range(char *buf, int left, int right)
{
    while (left < right) {
        char t = buf[left];
        buf[left] = buf[right];
        buf[right] = t;
        left++;
        right--;
    }
}

int main(void)
{
    char buf[MAXLEN];
    int len, i, start;

    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        return 0;
    }
    len = (int)strlen(buf);
    while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r')) {
        buf[--len] = '\0';
    }
    /* 第一步：整句反转，单词顺序反了，但每个单词内部也反了 */
    reverse_range(buf, 0, len - 1);
    /* 第二步：把每个单词再反转回来 */
    i = 0;
    while (i < len) {
        while (i < len && buf[i] == ' ') {
            i++;
        }
        start = i;
        while (i < len && buf[i] != ' ') {
            i++;
        }
        reverse_range(buf, start, i - 1);
    }
    printf("%s\n", buf);
    return 0;
}

#include <stdio.h>

#define MAXM 25
#define MAXN 25

int main(void)
{
    int m, n, i, j;
    int t[MAXM][MAXN];
    int diff[MAXM];
    int best = 0;

    if (scanf("%d %d", &m, &n) != 2) {
        return 0;
    }
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
            if (scanf("%d", &t[i][j]) != 1) {
                return 0;
            }
        }
    }
    for (i = 0; i < m; i++) {
        int hi = t[i][0];
        int lo = t[i][0];
        for (j = 1; j < n; j++) {
            if (t[i][j] > hi) {
                hi = t[i][j];
            }
            if (t[i][j] < lo) {
                lo = t[i][j];
            }
        }
        diff[i] = hi - lo;
        if (diff[i] > diff[best]) {
            best = i;
        }
    }
    for (i = 0; i < m; i++) {
        printf(i == 0 ? "%d" : " %d", diff[i]);
    }
    printf("\n");
    printf("%d\n", best + 1);
    return 0;
}

