#define STACKMAX 256
#define TOKLEN 64

int main(void)
{
    long long st[STACKMAX];
    int top = 0;
    char tok[TOKLEN];

    while (scanf("%63s", tok) == 1) {
        size_t len = strlen(tok);
        if (len == 1 && (tok[0] == '+' || tok[0] == '-' ||
                         tok[0] == '*' || tok[0] == '/')) {
            long long b = st[--top];
            long long a = st[--top];
            long long r = 0;
            if (tok[0] == '+') {
                r = a + b;
            } else if (tok[0] == '-') {
                r = a - b;
            } else if (tok[0] == '*') {
                r = a * b;
            } else {
                r = a / b;
            }
            st[top++] = r;
        } else {
            st[top++] = strtoll(tok, NULL, 10);
        }
    }
    printf("%lld\n", st[top - 1]);
    return 0;
}

#include <stdio.h>
typedef struct {
    long long arrival, left, finish;
} Job;
static Job a[2000];
int main(void) {
    int n, done = 0;
    long long now = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%lld%lld", &a[i].arrival, &a[i].left);
    while (done < n) {
        int best = -1;
        long long next = 1LL << 60;
        for (int i = 0; i < n; i++) {
            if (!a[i].left)
                continue;
            if (a[i].arrival > now) {
                if (a[i].arrival < next)
                    next = a[i].arrival;
            } else if (best < 0 || a[i].left < a[best].left)
                best = i;
        }
        if (best < 0) {
            now = next;
            continue;
        }
        long long dt = a[best].left;
        if (next - now < dt)
            dt = next - now;
        now += dt;
        a[best].left -= dt;
        if (!a[best].left) {
            a[best].finish = now;
            done++;
        }
    }
    for (int i = 0; i < n; i++)
        printf("%lld\n", a[i].finish);
    return 0;
}

