#include <stdio.h>

#define MAXN 105

typedef struct {
    char code[16];      /* 课程代码 */
    int credit;         /* 学分 */
    int score;          /* 百分制分数 */
    int gp10;           /* 绩点 × 10，用整数保存避免浮点误差 */
} Course;

/* 按分数查绩点（返回绩点 × 10） */
int lookup_gp10(int score)
{
    if (score >= 90) {
        return 40;
    } else if (score >= 85) {
        return 37;
    } else if (score >= 82) {
        return 33;
    } else if (score >= 78) {
        return 30;
    } else if (score >= 75) {
        return 27;
    } else if (score >= 72) {
        return 23;
    } else if (score >= 68) {
        return 20;
    } else if (score >= 64) {
        return 15;
    } else if (score >= 60) {
        return 10;
    }
    return 0;
}

int main(void)
{
    Course c[MAXN];
    int n, i;
    long long sum_num = 0;
    long long sum_credit = 0;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        if (scanf("%15s %d %d", c[i].code, &c[i].credit, &c[i].score) != 3) {
            return 0;
        }
        c[i].gp10 = lookup_gp10(c[i].score);
        sum_num += (long long)c[i].credit * c[i].gp10;
        sum_credit += c[i].credit;
    }
    for (i = 0; i < n; i++) {
        printf("%s %d %d.%d\n", c[i].code, c[i].credit,
               c[i].gp10 / 10, c[i].gp10 % 10);
    }
    if (sum_credit > 0) {
        printf("GPA %.2f\n", (double)sum_num / (double)(sum_credit * 10));
    } else {
        printf("GPA 0.00\n");
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int n, i;
    int cap = 2;
    int cnt = 0;
    long long sum = 0;
    int *buf = (int *)malloc(sizeof(int) * (size_t)cap);

    if (buf == NULL) {
        return 1;
    }
    if (scanf("%d", &n) != 1) {
        free(buf);
        return 0;
    }
    for (i = 0; i < n; i++) {
        int x = 0;
        if (scanf("%d", &x) != 1) {
            break;
        }
        if (cnt == cap) {              /* 缓冲区已满，容量翻倍 */
            int newcap = cap * 2;
            int *p = (int *)realloc(buf, sizeof(int) * (size_t)newcap);
            if (p == NULL) {
                free(buf);
                return 1;
            }
            buf = p;
            cap = newcap;
        }
        buf[cnt++] = x;
        sum += x;
    }
    printf("%d %d %lld\n", cap, cnt, sum);
    free(buf);
    return 0;
}

#include <stdio.h>

#define MAXN 25

/* 胜一场 3 分，平一场 1 分，负一场 0 分 */
int point(int ga, int gb)
{
    if (ga > gb) {
        return 3;
    }
    if (ga == gb) {
        return 1;
    }
    return 0;
}

int main(void)
{
    int n, m, i, j;
    int points[MAXN] = {0};
    int gd[MAXN] = {0};
    int order[MAXN];

    if (scanf("%d %d", &n, &m) != 2) {
        return 0;
    }
    for (i = 0; i < m; i++) {
        int a = 0, b = 0, ga = 0, gb = 0;
        if (scanf("%d %d %d %d", &a, &b, &ga, &gb) != 4) {
            return 0;
        }
        gd[a] += ga - gb;
        gd[b] += gb - ga;
        points[a] += point(ga, gb);
        points[b] += point(gb, ga);
    }
    for (i = 0; i < n; i++) {
        order[i] = i + 1;
    }
    for (i = 0; i < n - 1; i++) {
        int k = i;
        for (j = i + 1; j < n; j++) {
            int x = order[j];
            int y = order[k];
            if (points[x] > points[y] ||
                (points[x] == points[y] && gd[x] > gd[y]) ||
                (points[x] == points[y] && gd[x] == gd[y] && x < y)) {
                k = j;
            }
        }
        if (k != i) {
            int t = order[i];
            order[i] = order[k];
            order[k] = t;
        }
    }
    for (i = 0; i < n; i++) {
        int id = order[i];
        printf("%d %d %d\n", id, points[id], gd[id]);
    }
    return 0;
}

#include <stdio.h>

#define MAXN 2005

/* 判断能否按顺序把包裹切成不超过 m 段，使每段重量之和都不超过 limit */
static int feasible(const long long *w, int n, int m, long long limit)
{
    int used = 1;
    long long cur = 0;
    int i;

    for (i = 0; i < n; i++) {
        if (w[i] > limit) {
            return 0;
        }
        if (cur + w[i] <= limit) {
            cur += w[i];
        } else {
            used++;
            cur = w[i];
        }
    }
    return used <= m;
}

int main(void)
{
    static long long w[MAXN];
    int n, m, i;
    long long lo = 0, hi = 0, ans = 0;

    if (scanf("%d %d", &n, &m) != 2) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        if (scanf("%lld", &w[i]) != 1) {
            return 0;
        }
        if (w[i] > lo) {
            lo = w[i];      /* 下界：单个最重的包裹 */
        }
        hi += w[i];         /* 上界：全部由一个分拣员承担 */
    }
    ans = hi;
    /* 二分答案：最小的「单段重量上限」，使段数不超过 m */
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;
        if (feasible(w, n, m, mid)) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    printf("%lld\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
typedef struct {
    int a, b, cost;
} Edge;
static Edge edges[200000];
static int parent[100001];
int root(int x) {
    while (x != parent[x]) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}
int cmp(const void *a, const void *b) {
    const Edge *x = a, *y = b;
    return x->cost - y->cost;
}
int main(void) {
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++)
        parent[i] = i;
    for (int i = 0; i < m; i++)
        scanf("%d%d%d", &edges[i].a, &edges[i].b, &edges[i].cost);
    qsort(edges, m, sizeof(Edge), cmp);
    int parts = n;
    long long total = 0;
    for (int i = 0; i < m; i++) {
        int a = root(edges[i].a), b = root(edges[i].b);
        if (a != b) {
            parent[a] = b;
            parts--;
            total += edges[i].cost;
        }
    }
    printf("%lld\n", parts == 1 ? total : -1LL);
    return 0;
}

#include <stdio.h>
