#define MAXLEN 32

/* 把 1..3999 的整数转换成罗马数字，结果写入 out（调用者保证空间足够） */
void to_roman(int n, char *out)
{
    const int val[13] = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
    const char *sym[13] = {"M", "CM", "D", "CD", "C", "XC", "L", "XL",
                           "X", "IX", "V", "IV", "I"};
    int i;

    out[0] = '\0';
    for (i = 0; i < 13; i++) {
        while (n >= val[i]) {
            strcat(out, sym[i]);
            n -= val[i];
        }
    }
}

int main(void)
{
    char buf[MAXLEN];
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n < 1 || n > 3999) {
        return 0;
    }
    to_roman(n, buf);
    printf("%s\n", buf);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXLEN 2048

int main(void)
{
    char buf[MAXLEN];
    char *p = buf;
    int cnt = 0;
    int maxv = 0;
    long long sum = 0;

    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        return 0;
    }
    for (;;) {
        char *end = NULL;
        long v;
        while (*p == ' ') {
            p++;
        }
        if (*p == '\0' || *p == '\n' || *p == '\r') {
            break;
        }
        v = strtol(p, &end, 10);
        if (end == p) {         /* 不是整数（例如多余的逗号），跳过 */
            p++;
            continue;
        }
        if (cnt == 0 || (int)v > maxv) {
            maxv = (int)v;
        }
        cnt++;
        sum += v;
        p = end;
        if (*p == ',') {
            p++;
        }
    }
    printf("%d %lld %d\n", cnt, sum, maxv);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int n, m, i;
    int *d;

    if (scanf("%d %d", &n, &m) != 2) {
        return 0;
    }
    /* 下标 1..n 存差分值，多留一位给 r+1 */
    d = (int *)calloc((size_t)n + 2, sizeof(int));
    if (d == NULL) {
        return 1;
    }
    for (i = 0; i < m; i++) {
        int l = 0, r = 0;
        if (scanf("%d %d", &l, &r) != 2) {
            break;
        }
        d[l] += 1;
        d[r + 1] -= 1;
    }
    for (i = 1; i <= n; i++) {
        d[i] += d[i - 1];       /* 前缀和还原每个路段的次数 */
    }
    for (i = 1; i <= n; i++) {
        printf(i == 1 ? "%d" : " %d", d[i]);
    }
    printf("\n");
    free(d);
    return 0;
}

#include <stdio.h>

#define MAXMN 205

int main(void)
{
    static long long pre[MAXMN][MAXMN];
    int m, n, q, i, j;

    if (scanf("%d %d %d", &m, &n, &q) != 3) {
        return 0;
    }
    for (i = 1; i <= m; i++) {
        for (j = 1; j <= n; j++) {
            long long x = 0;
            if (scanf("%lld", &x) != 1) {
                return 0;
            }
            pre[i][j] = pre[i - 1][j] + pre[i][j - 1] - pre[i - 1][j - 1] + x;
        }
    }
    for (i = 0; i < q; i++) {
        int r1 = 0, c1 = 0, r2 = 0, c2 = 0;
        if (scanf("%d %d %d %d", &r1, &c1, &r2, &c2) != 4) {
            return 0;
        }
        printf("%lld\n", pre[r2][c2] - pre[r1 - 1][c2]
                         - pre[r2][c1 - 1] + pre[r1 - 1][c1 - 1]);
    }
    return 0;
}

#include <stdio.h>

#define MAXC 26

typedef struct {
    char cat;          /* 类别字母 */
    int count;         /* 笔数 */
    long long total;   /* 报销总额 */
} Ledger;

int main(void)
{
    Ledger led[MAXC];
    int size = 0;
    int n, i, j;
    long long all = 0;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        int id = 0;
        char cat[4];
        long long amount = 0;
        if (scanf("%d %3s %lld", &id, cat, &amount) != 3) {
            continue;
        }
        for (j = 0; j < size; j++) {
            if (led[j].cat == cat[0]) {
                break;
            }
        }
        if (j == size) {                /* 新类别 */
            led[size].cat = cat[0];
            led[size].count = 0;
            led[size].total = 0;
            size++;
        }
        led[j].count += 1;
        led[j].total += amount;
        all += amount;
    }
    /* 按总额降序、类别字母升序排序 */
    for (i = 0; i < size - 1; i++) {
        int k = i;
        for (j = i + 1; j < size; j++) {
            if (led[j].total > led[k].total ||
                (led[j].total == led[k].total && led[j].cat < led[k].cat)) {
                k = j;
            }
        }
        if (k != i) {
            Ledger t = led[i];
            led[i] = led[k];
            led[k] = t;
        }
    }
    for (i = 0; i < size; i++) {
        double pct;
        if (all > 0) {
            pct = (double)led[i].total * 100.0 / (double)all;
        } else {
            pct = 0.0;
        }
        printf("%c %d %lld %.1f\n", led[i].cat, led[i].count, led[i].total, pct);
    }
    return 0;
}

#include <stdio.h>
static long long p[200002];
static int idx[200002];
int main(void) {
    int n, head = 0, tail = 0;
    long long s;
    scanf("%d%lld", &n, &s);
    int best = n + 1;
    for (int i = 0; i <= n; i++) {
        if (i) {
            long long x;
            scanf("%lld", &x);
            p[i] = p[i - 1] + x;
        }
        while (head < tail && p[i] - p[idx[head]] >= s) {
            int len = i - idx[head++];
            if (len < best)
                best = len;
        }
        while (head < tail && p[idx[tail - 1]] >= p[i])
            tail--;
        idx[tail++] = i;
    }
    printf("%d\n", best > n ? -1 : best);
    return 0;
}
